'use strict';
let D,customers,orderMap,ticketMap,eventMap,view='Overview',page=1,query='',riskFilter='',productFilter='',channelFilter='',segmentFilter='',valueFilter='',lastFilter='',frequencyFilter='',cohortChannel='',cohortProduct='',period=90,sort='risk',selected=null;
const navs=['Overview','Customer Intelligence','Churn Intelligence','Customer Segments','Retention Actions','Campaign Intelligence','Cohort Analysis','Product Analytics','Model Intelligence','Reports','Settings'];
const icons=['▦','♙','◈','◫','⚑','▤','▥','◎','▧','⚙'];
const colors={Low:'#78a481',Medium:'#d3bb70',High:'#d99a69',Critical:'#c86c60',Unscored:'#aaa'};
const labels={overdue_ratio:'Missed expected replenishment',order_count:'Completed purchase history',frequency_ratio:'Replenishment frequency change',cancellations:'Order cancellations',refunds:'Refund history',open_tickets:'Unresolved support tickets',engagement_30d:'Recent engagement',spend:'Historical customer value',tenure:'Customer tenure'};
const fmt=n=>new Intl.NumberFormat('en-IN',{maximumFractionDigits:0}).format(n||0),money=n=>'₹'+(n>=1e7?(n/1e7).toFixed(2)+'Cr':n>=1e5?(n/1e5).toFixed(2)+'L':fmt(n)),pct=n=>(100*(n||0)).toFixed(1)+'%',date=s=>new Date(s+'T00:00:00Z'),days=(a,b)=>Math.floor((date(a)-date(b))/86400000),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),short=s=>date(s).toLocaleDateString('en-IN',{day:'numeric',month:'short',timeZone:'UTC'});
const getStore=(k,d)=>{try{return JSON.parse(localStorage.getItem('rr-'+k))??d}catch{return d}},put=(k,v)=>localStorage.setItem('rr-'+k,JSON.stringify(v));
const apiMode=!!window.API_MODE;
let authToken=sessionStorage.getItem('rr-token');
async function api(path,method='GET',body){const res=await fetch('/api/'+path,{method,headers:{Authorization:'Bearer '+authToken,'Content-Type':'application/json'},...(body?{body:JSON.stringify(body)}:{})});if(!res.ok){const err=await res.json().catch(()=>({detail:'Request failed'}));throw Error(typeof err.detail==='string'?err.detail:'Please check the form fields.')}return res.json()}
function backendLogin(){document.getElementById('app').innerHTML=`<div class="loading"><div class="panel" style="width:380px;max-width:95vw"><h1>Retention Radar</h1><p style="margin:12px 0 24px">Sign in to the synthetic demo workspace</p><form class="form" onsubmit="signIn(event)"><label>Email<input name="email" type="email" required placeholder="manager@radar.demo"></label><label>Password<input name="password" type="password" required></label><button class="primary">Sign in</button><small id="login-error"></small></form></div></div>`}
async function signIn(e){e.preventDefault();try{const result=await api('auth/login','POST',Object.fromEntries(new FormData(e.target)));authToken=result.access_token;sessionStorage.setItem('rr-token',authToken);await init()}catch(err){document.getElementById('login-error').textContent=err.message}}
async function syncOperations(){const rows=await api('interventions');interventions=rows.map(i=>({...i,customer:i.customer_id,created:D.asOf,history:JSON.parse(i.history||'[]')}));campaigns=await api('campaigns')}
let settings=getStore('settings',{grace:14,horizon:30,medium:.35,high:.6,critical:.8,role:'Retention Manager'}),interventions=getStore('interventions',[]),campaigns=getStore('campaigns',[]);
function toast(s){const t=document.getElementById('toast');t.textContent=s;t.style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>t.style.display='none',3800)}
function risk(p){return p==null?'Unscored':p>=settings.critical?'Critical':p>=settings.high?'High':p>=settings.medium?'Medium':'Low'}
function pill(c){return `<span class="pill ${c.risk}">${c.risk}${c.risk!=='Unscored'?' risk':''}</span>`}
function avatar(c){return `<span class="avatar">${c.name.split(' ').map(x=>x[0]).join('')}</span>`}
function reason(c){if(c.openTickets)return 'Unresolved support concern';if(c.overdue>settings.grace)return `${c.overdue} days past expected refill`;if(c.cancellations>1)return 'Repeated order cancellations';if(c.engagement<2)return 'Low recent engagement';return 'Changing purchase frequency'}
function recommendation(c){if(c.openTickets)return 'Prioritise a support follow-up; route treatment-related concerns to a qualified professional.';if(c.cancellations>1)return 'Request feedback on cancellations and investigate delivery or affordability concerns.';if(c.overdue>0)return 'Send a personalised replenishment reminder with a convenient reorder link.';return 'Share approved product education and offer personalised assistance.'}
function stage(c){if(c.count===1&&days(D.asOf,c.first)<45)return 'New';if(c.overdue>c.cycle+settings.grace)return 'Dormant';if(c.risk==='Critical'||c.risk==='High')return 'At-Risk';if(c.recovered)return 'Recovered';if(c.count>=4&&c.freq<=c.cycle*1.3)return 'Consistent';return 'Active'}
function refresh(){customers=D.customers.map(c=>{const os=orderMap[c.id]||[],completed=os.filter(x=>x.status==='completed'),p=D.products[c.product],last=completed.at(-1)?.date||c.first,gaps=completed.slice(1).map((o,i)=>days(o.date,completed[i].date)),lastDays=days(D.asOf,last),openTickets=(ticketMap[c.id]||[]).filter(t=>t.status==='Open').length;const z={...c,orders:os,completed,count:completed.length,revenue:completed.reduce((s,o)=>s+o.amount,0),last,cycle:p.cycle,overdue:lastDays-p.cycle,lastDays,freq:gaps.length?gaps.reduce((s,v)=>s+v,0)/gaps.length:0,recovered:gaps.some(g=>g>p.cycle*1.6),openTickets,cancellations:os.filter(o=>o.status==='cancelled').length,engagement:(eventMap[c.id]||[]).filter(e=>days(D.asOf,e.date)<=30).length,risk:risk(c.probability)};z.stage=stage(z);return z})}
function scoped(){return customers.filter(c=>(!channelFilter||c.channel===channelFilter)&&(!productFilter||c.product===Number(productFilter)-1))}
function filtered(){return scoped().filter(c=>(!query||(c.name+' '+c.code).toLowerCase().includes(query.toLowerCase()))&&(!riskFilter||c.risk===riskFilter)&&(!segmentFilter||(segmentFilter==='High-Value'?c.revenue>=5000:c.stage===segmentFilter))&&(!valueFilter||c.revenue>Number(valueFilter))&&(!lastFilter||c.lastDays>=Number(lastFilter))&&(!frequencyFilter||c.freq>=Number(frequencyFilter))).sort((a,b)=>sort==='name'?a.name.localeCompare(b.name):sort==='value'?b.revenue-a.revenue:(b.probability??-1)-(a.probability??-1))}
function metrics(list, asof = D.asOf) {
  const asofTime = date(asof).getTime();
  const periodStart = new Date(asofTime - period * 86400000).toISOString().slice(0, 10);
  const currentSnapshot = asof === D.asOf;
  const daysSincePurchase = new Map();
  let active = 0, eligible = 0, repeatBuyers = 0, riskn = 0, scored = 0;
  let probability = 0, rev = 0, atrisk = 0, recent = 0, retained = 0;

  for (const customer of list) {
    if (customer.probability != null) {
      probability += customer.probability;
      scored++;
    }
    let lastDate, count = 0, revenue = 0, periodRevenue = 0, repeatRevenue = 0;
    for (const order of customer.completed) {
      if (order.date >= asof) continue;
      if (order.date >= periodStart) {
        periodRevenue += order.amount;
        if (count > 0) repeatRevenue += order.amount;
      }
      lastDate = order.date;
      revenue += order.amount;
      count++;
    }
    if (!count) continue;

    let since = daysSincePurchase.get(lastDate);
    if (since === undefined) {
      since = Math.floor((asofTime - date(lastDate).getTime()) / 86400000);
      daysSincePurchase.set(lastDate, since);
    }
    const late = since > customer.cycle + settings.grace;
    const atRisk = currentSnapshot ? customer.risk === 'High' || customer.risk === 'Critical' : late;
    eligible++;
    active += !late;
    repeatBuyers += count > 1;
    riskn += atRisk;
    if (atRisk) atrisk += currentSnapshot ? customer.revenue * customer.probability : revenue;
    rev += revenue;
    recent += periodRevenue;
    retained += repeatRevenue;
  }

  const buyers = Math.max(1, eligible);
  return {
    active, riskn, pred: probability / Math.max(1, scored), retention: active / buyers,
    repeat: repeatBuyers / buyers, clv: rev / buyers, atrisk, retained, rev, recent,
    churn: (eligible - active) / buyers, eligible
  };
}
function shell(){document.getElementById('app').innerHTML=`<aside class="sidebar"><div class="brand"><span class="brand-icon">R</span><span class="brand-text">retention radar<span style="color:#b4d397">.</span></span></div><button class="collapse-btn" aria-label="Collapse sidebar" onclick="document.body.classList.toggle('collapsed')">‹</button><div class="workspace"><span class="mm">mm.</span><div><strong>Man Matters</strong><small>Retention workspace</small></div><span style="margin-left:auto">⌄</span></div><div class="nav-label">WORKSPACE</div><nav class="nav">${navs.map((n,i)=>`${i===8?'<div class="nav-label" style="margin-top:20px">MANAGEMENT</div>':''}<button title="${n}" class="${view===n?'active':''}" onclick="navigate('${n}')"><span class="nav-icon">${navIcon(i)}</span><span class="label">${n}</span>${n==='Retention Actions'?`<span class="count">${interventions.filter(x=>!['Resolved','Unsuccessful'].includes(x.status)).length}</span>`:''}</button>`).join('')}</nav><div class="side-bottom"><div class="health"><i></i> Synthetic workspace · v2</div><div class="user"><span class="avatar">AS</span><div><strong>Ananya Sharma</strong><small>${esc(settings.role)}</small></div></div></div></aside><main class="main"><header class="topbar"><div style="display:flex;align-items:center;gap:10px"><button class="mobile-menu" aria-label="Toggle navigation" onclick="document.body.classList.toggle('show-menu')">☰</button><div class="breadcrumb">Workspace <span style="margin:0 10px">/</span><b>${view}</b></div></div><div class="top-actions"><input aria-label="Global customer search" placeholder="⌕  Search customers…" onkeydown="if(event.key==='Enter'){query=this.value;navigate('Customer Intelligence',true)}"><span class="badge"><i class="status-dot"></i> Demo workspace</span><span class="avatar">AS</span></div></header><div class="demo"><span>ⓘ</span><strong>Synthetic demo data</strong><span>Explore freely. These records do not represent actual Man Matters customers.</span><span>As of 01 Nov 2026</span></div><section class="content" id="content"></section></main>`;renderContent()}
function navigate(n,keep=false){view=n;page=1;if(!keep){query='';riskFilter='';segmentFilter='';productFilter='';channelFilter='';valueFilter='';lastFilter='';frequencyFilter=''}document.body.classList.remove('show-menu');history.replaceState(null,'','#'+encodeURIComponent(n));shell();window.scrollTo(0,0)}
function header(title,sub,actions=true){return `<div class="page-head"><div><h1>${title}</h1><p>${sub}</p></div>${actions?`<div class="actions"><select class="date-select" aria-label="Reporting period" onchange="period=Number(this.value);renderContent()">${[30,60,90,180,365].map(n=>`<option value="${n}" ${period===n?'selected':''}>▣ Last ${n} days</option>`).join('')}</select><button onclick="exportReport('summary')">⇩ &nbsp; Export report</button></div>`:''}</div>`}
function spark(values,color='#71a276'){const max=Math.max(...values,1),min=Math.min(...values);return `<svg class="spark" viewBox="0 0 60 23"><polyline points="${values.map((x,i)=>`${i*60/(values.length-1)},${21-(x-min)/Math.max(1,max-min)*17}`).join(' ')}" stroke="${color}" stroke-width="1.6" fill="none"/></svg>`}
function metric(label,current,previous,type,tip,lower=false,trend=[]){const delta=previous?((current-previous)/Math.abs(previous))*100:0;return `<div class="metric"><div class="metric-top"><span>${label}</span><span title="${esc(tip)}">ⓘ</span></div><div class="metric-value">${type==='money'?money(current):type==='pct'?pct(current):fmt(current)}</div><div class="metric-foot"><span><span class="delta ${(lower?delta>0:delta<0)?'bad':''}">${delta>=0?'↗':'↘'} ${Math.abs(delta).toFixed(1)}%</span> &nbsp; vs prior period</span>${spark(trend.length?trend:[previous,current])}</div></div>`}
function months(){return Array.from({length:7},(_,i)=>{const d=new Date(Date.UTC(2026,3+i,1));return {label:d.toLocaleDateString('en',{month:'short',timeZone:'UTC'}),end:new Date(Date.UTC(2026,4+i,1)).toISOString().slice(0,10)}})}
function series(list){return months().map(m=>({...m,...metrics(list,m.end)}))}
function lineChart(data,keys,cols,percent=true){const w=600,h=205,max=Math.max(...data.flatMap(d=>keys.map(k=>d[k])),.01)*1.25;return `<svg class="chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="Monthly ${keys.join(' and ')} trend">${[0,1,2,3,4].map(i=>`<line class="gridline" x1="40" x2="580" y1="${15+i*39}" y2="${15+i*39}"/><text x="0" y="${19+i*39}">${percent?pct(max*(1-i/4)):money(max*(1-i/4))}</text>`).join('')}${keys.map((key,j)=>{const points=data.map((d,i)=>`${45+i*(528/Math.max(1,data.length-1))},${171-d[key]/max*156}`).join(' ');return `<polygon points="45,171 ${points} 573,171" fill="${cols[j]}" opacity=".045"/><polyline points="${points}" fill="none" stroke="${cols[j]}" stroke-width="2.5" ${j?'stroke-dasharray="5 4"':''}/>${data.map((d,i)=>`<circle cx="${45+i*(528/Math.max(1,data.length-1))}" cy="${171-d[key]/max*156}" r="3" fill="white" stroke="${cols[j]}" stroke-width="2"><title>${d.label} · ${key}: ${percent?pct(d[key]):money(d[key])}</title></circle>`).join('')}`}).join('')}${data.map((d,i)=>`<text x="${45+i*(528/Math.max(1,data.length-1))}" y="198" text-anchor="middle">${d.label}</text>`).join('')}</svg>`}
function panel(title,sub,body,extra=''){return `<div class="panel"><div class="panel-head"><div><h2>${title}</h2><p>${sub}</p></div>${extra}</div>${body}</div>`}
function overview(){const list=scoped(),m=metrics(list),priorDate=new Date(date(D.asOf)-period*86400000).toISOString().slice(0,10),prev=metrics(list,priorDate),s=series(list),alerts=[...list].filter(c=>['Critical','High'].includes(c.risk)).sort((a,b)=>b.probability-a.probability).slice(0,5),dist=Object.keys(colors).map(k=>({k,n:list.filter(c=>c.risk===k).length})).filter(x=>x.n),total=list.length;let stop=0;const donut=dist.map(x=>{const from=stop;stop+=x.n/total*100;return `${colors[x.k]} ${from}% ${stop}%`}).join(',');return header('Retention overview',"A clearer picture of customer health. A smarter path to retention.")+`<div class="pulse"><div class="pulse-icon">✧</div><div><p><strong>${fmt(m.riskn)} customers could use your attention.</strong> Start with high-value customers who missed their refill.</p><small>Model-assisted prioritisation · ${D.model.selected} · 30-day prediction window</small></div><button onclick="riskFilter='Critical';navigate('Customer Intelligence',true)">Review at-risk customers &nbsp; ↗</button></div><div class="metrics">${metric('Active customers',m.active,prev.active,'num','Customers within their product-specific refill cycle plus grace.',false,s.map(x=>x.active))}${metric('Customers at risk',m.riskn,prev.riskn,'num','Current: high and critical model risk. Prior: observed missed refill proxy; not directly comparable.',true,s.map(x=>x.riskn))}${metric('Predicted churn rate',m.pred,prev.churn,'pct','Mean model probability for scored customers. Prior uses observed missed refill rate; proxy comparison.',true,s.map(x=>x.churn))}${metric('Customer retention rate',m.retention,prev.retention,'pct','Share within product-specific expected refill window plus grace.',false,s.map(x=>x.retention))}${metric('Repeat purchase rate',m.repeat,prev.repeat,'pct','Share of customers with at least two completed orders.',false,s.map(x=>x.repeat))}${metric('Average customer value',m.clv,prev.clv,'money','Observed completed revenue per purchasing customer; historical CLV proxy, not a forecast.',false,s.map(x=>x.clv))}${metric('Revenue at risk',m.atrisk,prev.atrisk,'money','Historical value × model probability for high/critical customers. Exposure proxy, not forecast lost revenue. Prior uses observed overdue value.',true,s.map(x=>x.atrisk))}${metric('Repeat-order revenue',m.retained,prev.retained,'money','Completed repeat-order revenue in reporting period. Does not establish intervention impact.',false,s.map(x=>x.retained))}</div><div class="grid">${panel('Customer churn trend','Observed missed-refill rate over time',lineChart(s,['churn'],['#4c8666']),'<span class="legend"><i style="background:#4c8666"></i>Observed churn proxy</span>')}${panel('Customer risk distribution','A live view of your customer portfolio',`<div class="risk-content"><div class="donut" style="background:conic-gradient(${donut})"><div class="donut-label"><strong>${fmt(total)}</strong><small>total customers</small></div></div><div class="risk-legend">${dist.map(x=>`<div class="risk-row" role="button" tabindex="0" onclick="riskFilter='${x.k}';navigate('Customer Intelligence',true)" onkeydown="if(event.key==='Enter')this.click()"><i style="background:${colors[x.k]}"></i>${x.k} risk<b>${fmt(x.n)}</b><small>${Math.round(x.n/total*100)}%</small></div>`).join('')}</div></div><div class="risk-note">↗ &nbsp; Select a risk group to explore its customers</div>`)}</div><div class="two-grid">${panel('Revenue exposure by product','Risk-weighted historical customer value',barChart(list,'exposure'))}${panel('Customer retention trend','Within expected refill window + grace',lineChart(s,['retention'],['#5a8969']))}</div><div class="grid">${customerTable(alerts,'Customers to prioritise','Highest predicted risk · ranked for follow-up',false,true)}${panel('Product-wise churn','Observed missed replenishment, by category',D.products.map(p=>{const cs=list.filter(c=>c.product===p.id),v=metrics(cs).churn;return `<div class="hbar-row"><span>${p.name}</span><div class="hbar-track"><div style="width:${v*100}%"></div></div><b>${pct(v)}</b></div>`}).join(''),'<button onclick="navigate(\'Product Analytics\')">Explore ↗</button>')}</div><div class="forecast-note">Comparisons for predicted risk and exposure use observed historical proxies. Historical customer value is not a forecast. Campaign and intervention outcomes are observational.</div>`}
function barChart(list,kind){const vals=D.products.map(p=>{const cs=list.filter(c=>c.product===p.id);return {p,v:kind==='exposure'?metrics(cs).atrisk:metrics(cs).rev}}),max=Math.max(...vals.map(x=>x.v),1);return `<div class="bars">${vals.map(x=>`<div class="bar-wrap"><small>${money(x.v)}</small><div class="bar" style="height:${x.v/max*130}px" tabindex="0" role="button" onclick="productFilter='${x.p.id+1}';navigate('Customer Intelligence',true)" onkeydown="if(event.key==='Enter')this.click()" title="${x.p.name}: ${money(x.v)}"></div><span>${x.p.name.replace(' treatment','').replace('Haircare ','').replace('Hair ','')}</span></div>`).join('')}</div><div style="height:25px"></div>`}
function customerTable(list,title,sub,filters=false,compact=false){const all=list.length,start=filters?(page-1)*12:0,rows=filters?list.slice(start,start+12):list;return `<div class="panel table-panel"><div class="panel-head"><div><h2>${title}</h2><p>${sub}</p></div><button onclick="${compact?"navigate('Customer Intelligence')":"exportReport('customers')"}">${compact?'View all customers ↗':'⇩ Export CSV'}</button></div>${filters?filterBar():''}<div class="table-wrap"><table><thead><tr><th>Customer</th>${compact?'':'<th>Product / lifecycle</th>'}<th>Risk level</th><th>${D.model.horizon}-day inactivity risk</th><th>${compact?'Primary risk signal':'Customer value'}</th><th></th></tr></thead><tbody>${rows.map(c=>`<tr class="clickable" tabindex="0" onkeydown="if(event.key==='Enter')profile(${c.id})" onclick="profile(${c.id})"><td><div class="customer">${avatar(c)}<div><b>${c.name}</b><small>${c.code}</small></div></div></td>${compact?'':`<td>${D.products[c.product].name}<small style="display:block;margin-top:5px">${c.stage} · ${c.channel}</small></td>`}<td>${pill(c)}</td><td><span class="probability">${c.probability==null?'—':pct(c.probability)}<i><em style="width:${c.probability*100}%;background:${colors[c.risk]}"></em></i></span></td><td>${compact?esc(predictionSignal(c)):money(c.revenue)}</td><td style="color:#809274">↗</td></tr>`).join('')||'<tr><td colspan="6" class="empty">No matching customers. Try clearing a filter.</td></tr>'}</tbody></table></div><div class="footer"><span>${filters?`${all?start+1:0}–${Math.min(start+12,all)} of `:''}${fmt(all)} customers · Synthetic data</span>${filters?`<span><button onclick="if(page>1){page--;renderContent()}">←</button> &nbsp; Page ${page} of ${Math.max(1,Math.ceil(all/12))} &nbsp; <button onclick="if(page<${Math.ceil(all/12)}){page++;renderContent()}">→</button></span>`:`<span>Scored ${esc(D.asOf)}</span>`}</div></div>`}
function options(vals,current){return vals.map(v=>`<option value="${esc(v)}" ${String(v)===String(current)?'selected':''}>${esc(v)}</option>`).join('')}
function filterBar(){return `<div class="filters"><input aria-label="Search customers" placeholder="⌕ Search name or customer ID" value="${esc(query)}" oninput="query=this.value;page=1;debounceRender(this)"><select aria-label="Risk level" onchange="riskFilter=this.value;page=1;renderContent()"><option value="">All risk levels</option>${options(Object.keys(colors),riskFilter)}</select><select aria-label="Product category" onchange="productFilter=this.value;page=1;renderContent()"><option value="">All products</option>${D.products.map(p=>`<option value="${p.id+1}" ${String(p.id+1)===productFilter?'selected':''}>${p.name}</option>`).join('')}</select><select aria-label="Lifecycle stage" onchange="segmentFilter=this.value;page=1;renderContent()"><option value="">All lifecycle stages</option>${options(['New','Active','Consistent','At-Risk','Dormant','Recovered','High-Value'],segmentFilter)}</select><select aria-label="Acquisition channel" onchange="channelFilter=this.value;page=1;renderContent()"><option value="">All channels</option>${options(['Organic','Meta Ads','Google Ads','Referral','Influencer'],channelFilter)}</select><select aria-label="Customer value" onchange="valueFilter=this.value;page=1;renderContent()"><option value="">Any customer value</option><option value="2000" ${valueFilter==='2000'?'selected':''}>Value over ₹2,000</option><option value="5000" ${valueFilter==='5000'?'selected':''}>Value over ₹5,000</option></select><select aria-label="Last purchase" onchange="lastFilter=this.value;page=1;renderContent()"><option value="">Any last purchase</option>${[30,60,90].map(v=>`<option value="${v}" ${lastFilter===String(v)?'selected':''}>Last order ≥ ${v} days ago</option>`).join('')}</select><select aria-label="Purchase frequency" onchange="frequencyFilter=this.value;page=1;renderContent()"><option value="">Any frequency</option>${[30,45,60].map(v=>`<option value="${v}" ${frequencyFilter===String(v)?'selected':''}>Avg interval ≥ ${v} days</option>`).join('')}</select><select aria-label="Sort customers" onchange="sort=this.value;renderContent()">${[['risk','Highest risk'],['value','Highest value'],['name','Name A–Z']].map(([v,n])=>`<option value="${v}" ${sort===v?'selected':''}>${n}</option>`).join('')}</select><button onclick="query='';riskFilter='';segmentFilter='';productFilter='';channelFilter='';lastFilter='';frequencyFilter='';valueFilter='';page=1;renderContent()">Clear filters</button></div>`}
function debounceRender(input){clearTimeout(window.searchTimer);const pos=input.selectionStart;window.searchTimer=setTimeout(()=>{renderContent();const el=document.querySelector('.filters input');el?.focus();el?.setSelectionRange(pos,pos)},220)}
function intelligence(){return header('Customer intelligence','From customer signals to a complete customer story.')+customerTable(filtered(),'Your customer portfolio','Search, prioritise, and understand every customer',true)}
function profile(id){selected=id;const c=customers[id],events=[...c.orders.map(o=>({date:o.date,title:`${o.status==='completed'?'Purchased':o.status==='cancelled'?'Cancelled order for':'Refunded'} ${D.products[o.product].name}`,detail:`Order #${o.id} · ${money(o.amount)}`})),...(ticketMap[id]||[]).map(t=>({date:t.date,title:t.subject,detail:'Support ticket · '+t.status})),...(eventMap[id]||[]).map(e=>({date:e.date,title:e.type,detail:'Engagement activity'})),...interventions.filter(i=>i.customer===id).map(i=>({date:i.created,title:'Retention intervention · '+i.status,detail:i.notes||i.action}))].sort((a,b)=>b.date.localeCompare(a.date));const due=new Date(date(c.last).getTime()+c.cycle*86400000).toISOString().slice(0,10);openDrawer(`<div class="drawer-head"><h2>Customer profile</h2><button aria-label="Close profile" onclick="closeDrawer()">✕</button></div><div class="profile-title">${avatar(c)}<div><h2>${c.name}</h2><small>${c.code} · ${c.age} · ${c.channel}</small></div><div style="margin-left:auto">${pill(c)}</div></div><div class="profile-stats"><div><small>${D.model.horizon}-day inactivity risk</small><b>${c.probability==null?'Unscored':pct(c.probability)}</b></div><div><small>Customer value</small><b>${money(c.revenue)}</b></div><div><small>Completed orders</small><b>${c.count}</b></div></div><div class="panel"><h2>Customer overview</h2><div class="form-grid" style="margin-top:16px;font-size:11px;line-height:2.1"><div><small>Lifecycle</small><br>${c.stage}<br><small>Registered</small><br>${short(c.registered)} ${c.registered.slice(0,4)}<br><small>First purchase</small><br>${c.count ? short(c.completed[0].date)+' '+c.completed[0].date.slice(0,4) : 'No completed purchase'}<br><small>Average order value</small><br>${money(c.revenue/Math.max(1,c.count))}</div><div><small>Product / consumption cycle</small><br>${D.products[c.product].name} · ${c.cycle} days<br><small>Last completed purchase</small><br>${c.count ? short(c.last)+' '+c.last.slice(0,4) : 'No completed purchase'}<br><small>Expected replenishment</small><br>${c.count ? short(due)+' '+due.slice(0,4) : 'Awaiting first purchase'}<br><small>Average purchase interval</small><br>${c.freq?Math.round(c.freq)+' days':'Not enough repeat orders'}</div></div><p class="forecast-note">Engagement: ${c.engagement} events in 30 days. Risk trend unavailable: one current scoring snapshot. Commercial inactivity is not confirmed treatment discontinuation.</p></div>${scoreProfile(c)}<div class="panel"><h2>Customer journey</h2><p class="forecast-note">Orders, support, engagement, and retention history</p><div class="timeline">${events.map(e=>`<div class="timeline-item"><small>${short(e.date)} ${e.date.slice(0,4)}</small><b>${esc(e.title)}</b><br>${esc(e.detail)}</div>`).join('')}</div></div>`)}
function openDrawer(html){document.getElementById('overlay').innerHTML=`<div class="overlay-backdrop" onclick="if(event.target===this)closeDrawer()"><section class="drawer" role="dialog" aria-modal="true" aria-label="Customer workspace">${html}</section></div>`;document.body.style.overflow='hidden';document.querySelector('.drawer button')?.focus()}
function closeDrawer(){document.getElementById('overlay').innerHTML='';document.body.style.overflow=''}
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeDrawer();if(e.key==='Tab'&&document.querySelector('.drawer')){const els=[...document.querySelectorAll('.drawer button,.drawer input,.drawer select,.drawer textarea,.drawer [tabindex="0"]')],first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
function prediction(){const mm=D.model,m=mm.metrics[mm.selected];return header('Churn prediction','Transparent predictions. Product-aware signals. Human-led decisions.',false)+`<div class="notice">Synthetic demonstration model · Predictions are for a fixed 30-day horizon and 14-day model grace. Changing operational grace in Settings does not retrain the model. Customers without a completed order are unscored; the model target applies to refill-eligible customers.</div><div class="model-grid">${panel('Model performance',`${mm.selected} · held-out chronological test`, `<div class="stat-list">${[['Precision',m.precision],['Recall',m.recall],['F1 score',m.f1],['ROC-AUC',m.roc_auc],['PR-AUC',m.pr_auc],['Brier loss ↓',m.brier]].map(([k,v])=>`<div><small>${k}</small><strong>${k==='Brier loss ↓'?v.toFixed(3):pct(v)}</strong></div>`).join('')}</div><div class="insight"><b>Model target</b><br>${mm.target}<br><small>Evaluation threshold: ${pct(mm.threshold)}; UI risk bands are separate business thresholds.</small></div>`) }${panel('Confusion matrix','Held-out customers · rows actual, columns predicted',`<div class="matrix">${[['True negatives',m.confusion[0][0]],['False positives',m.confusion[0][1]],['False negatives',m.confusion[1][0]],['True positives',m.confusion[1][1]]].map(([n,v])=>`<div><b>${fmt(v)}</b><small>${n}</small></div>`).join('')}</div><p class="forecast-note">Customers are separated across train, validation, and test. Snapshot features precede prediction dates; labels mature before the next split.</p>`)}</div><div class="two-grid" style="margin-top:18px">${panel('Baseline comparison','Selected by validation PR-AUC; these are held-out test results',`<div class="table-wrap"><table><thead><tr><th>Model</th><th>Recall</th><th>PR-AUC</th><th>Brier</th></tr></thead><tbody>${Object.entries(mm.metrics).map(([k,v])=>`<tr><td>${k}${k===mm.selected?' ✓':''}</td><td>${pct(v.recall)}</td><td>${pct(v.pr_auc)}</td><td>${v.brier.toFixed(3)}</td></tr>`).join('')}</tbody></table></div><p class="forecast-note">Last trained: ${esc(mm.trained)} · training ${mm.splitCounts[0]}, validation ${mm.splitCounts[1]}, test ${mm.splitCounts[2]} eligible observations.</p><p class="forecast-note">Train ${mm.splitDates[0]} → validation ${mm.splitDates[1]} → test ${mm.splitDates[2]}. Performance on synthetic data does not establish production performance.</p>`) }${panel('Calibration reliability','Mean prediction versus observed churn rate',`<div class="table-wrap"><table><thead><tr><th>Mean predicted</th><th>Observed</th><th>Difference</th></tr></thead><tbody>${m.calibration.map(([p,o])=>`<tr><td>${pct(p)}</td><td>${pct(o)}</td><td>${((p-o)*100).toFixed(1)} pp</td></tr>`).join('')}</tbody></table></div>`)}</div>${panel('Feature availability','Nine pre-snapshot features used in the current model',`<div class="filters" style="padding:0">${mm.features.map(f=>`<span class="badge">✓ ${labels[f]||f}</span>`).join('')}</div><p class="forecast-note">Unavailable and excluded: ${mm.unavailable.join(', ')}. Missing numeric inputs are median-imputed from training data. Explanations use feature replacement sensitivity, not SHAP or causal attribution.</p><div class="insight">A 60- or 90-day model requires a fresh training run with sufficiently mature labels. Use the Python training pipeline in the downloadable source; the hosted demo never rescales probabilities to invent a different horizon.</div>`)}`}
function segmentation(){const defs=[['New','Recently acquired, first-time purchasers'],['Active','Within their expected customer lifecycle'],['Consistent','Four or more orders, regular replenishment'],['At-Risk','High or critical predicted risk'],['Dormant','Beyond cycle + grace + an additional cycle'],['High-Value','₹5,000+ observed customer value'],['Recovered','A purchase after a gap of 1.6× product cycle']];return header('Customer segmentation','Find the customer groups that need a different approach.')+`<p class="section-intro">Lifecycle groups follow the priority New → Dormant → At-Risk → Recovered → Consistent → Active. High-value is an overlapping commercial segment. Retention uses product-specific refill windows.</p><div class="segment-grid">${defs.map(([n,desc])=>{const cs=customers.filter(c=>n==='High-Value'?c.revenue>=5000:c.stage===n),m=metrics(cs);return `<div class="panel segment-card" role="button" tabindex="0" onclick="segmentFilter='${n}';navigate('Customer Intelligence',true)" onkeydown="if(event.key==='Enter')this.click()"><div class="panel-head"><h2>${n.replace('-',' ')} customers</h2><span>↗</span></div><strong>${fmt(cs.length)}</strong><p>${desc}</p><div class="insight">Revenue ${money(m.rev)}<br>Retention ${pct(m.retention)} · Observed churn ${pct(m.churn)}</div></div>`}).join('')}</div>`}
function interventionForm(id,existingId=null){if(settings.role==='Business Analyst'){toast('Business Analyst is a read-only demo role. Switch roles in Settings to manage interventions.');return}const c=customers[id],old=interventions.find(x=>x.id===existingId);openDrawer(`<div class="drawer-head"><h2>${old?'Update':'Create'} intervention</h2><button onclick="closeDrawer()" aria-label="Close intervention">✕</button></div><div class="profile-title">${avatar(c)}<div><h2>${c.name}</h2><small>${c.code} · ${scoredProbability(c) ? pct(c.probability)+' '+D.model.horizon+'-day inactivity risk' : 'Unscored'}</small></div>${pill(c)}</div><div class="insight" style="margin-bottom:22px"><strong>Recommended action</strong><br>${predictionFollowUp(c)}<br><small>${esc(coverageMessage(c))}</small></div><form class="form" onsubmit="saveIntervention(event,${id},${existingId??'null'})"><label>Retention action<textarea name="action" required maxlength="2000">${esc(old?.action||predictionFollowUp(c))}</textarea></label><div class="form-grid"><label>Assigned executive<select name="assignee">${options(['Unassigned','Ananya Sharma','Priya Nair','Rohit Mehta','Neha Singh'],old?.assignee||'Unassigned')}</select></label><label>Follow-up deadline<input type="date" name="deadline" required value="${old?.deadline||'2026-11-04'}"></label><label>Status<select name="status">${options(['Pending','Assigned','In Progress','Contacted','Resolved','Unsuccessful'],old?.status||'Pending')}</select></label><label>Observed outcome<select name="outcome">${options(['Not observed','Resumed purchasing','Remained active','Churned','Customer responded','Customer opted out','Remained inactive'],old?.outcome||'Not observed')}</select></label></div><label>Follow-up notes / customer response<textarea name="notes" maxlength="4000" placeholder="Record context, responses, or escalation details…">${esc(old?.notes||'')}</textarea></label><p class="forecast-note">Stored in this browser in the hosted demo. Outcome records are observational and do not establish incremental retention.</p><button class="primary" type="submit">${old?'Save changes':'Create intervention'}</button></form>${old?`<div class="panel" style="margin-top:20px"><h2>Intervention history</h2><div class="timeline">${(old.history||[]).map(h=>`<div class="timeline-item"><small>${esc(h.at)}</small>${esc(h.status)} · ${esc(h.assignee)}<br>${esc(h.notes)}</div>`).join('')}</div></div>`:''}`)}
async function saveIntervention(e,cid,id){e.preventDefault();if(settings.role==='Business Analyst')return;const v=Object.fromEntries(new FormData(e.target));if(apiMode){try{await api('interventions'+(id?'/'+id:''),id?'PUT':'POST',{...v,customer_id:cid});await syncOperations();closeDrawer();shell();toast('Intervention saved to the database.')}catch(err){toast(err.message)}return}const old=interventions.find(i=>i.id===id),entry={...old,...v,id:id??Date.now(),customer:cid,created:old?.created||D.asOf,history:[...(old?.history||[]),{at:new Date().toISOString(),status:v.status,assignee:v.assignee,notes:v.notes}]};if(old)interventions=interventions.map(i=>i.id===id?entry:i);else interventions.unshift(entry);put('interventions',interventions);closeDrawer();shell();toast(old?'Intervention updated.':'Intervention created and added to your workspace.')}
function interventionCentre(){const list=interventions.filter(i=>!query||(customers[i.customer].name+' '+i.status+' '+i.assignee).toLowerCase().includes(query.toLowerCase())),resolved=interventions.filter(i=>i.status==='Resolved').length;return header('Intervention centre','Turn customer signals into thoughtful, accountable action.',false)+`<div class="metrics">${[['Open follow-ups',interventions.filter(i=>!['Resolved','Unsuccessful'].includes(i.status)).length],['Customers contacted',interventions.filter(i=>['Contacted','Resolved'].includes(i.status)).length],['Resolved cases',resolved],['Observed repeat purchases',interventions.filter(i=>i.outcome==='Resumed purchasing').length]].map(([n,v])=>`<div class="metric"><div class="metric-top">${n}</div><div class="metric-value">${fmt(v)}</div><small>Browser-local demonstration records</small></div>`).join('')}</div><div class="notice">Interventions and outcomes in this hosted demo are stored in your browser. No real customer communications are sent. A subsequent purchase does not prove an intervention caused recovery.</div><div class="panel table-panel"><div class="panel-head"><div><h2>Follow-up workspace</h2><p>Assign, follow up, record, and learn</p></div><button class="primary" onclick="navigate('Customer Intelligence')">＋ Select customer</button></div><div class="filters"><input aria-label="Search interventions" value="${esc(query)}" placeholder="Search customer, status, or executive" oninput="query=this.value;debounceIntervention(this)"><button onclick="exportReport('interventions')">⇩ Export CSV</button></div><div class="table-wrap"><table><thead><tr><th>Customer</th><th>Risk / reason</th><th>Assigned to</th><th>Follow-up</th><th>Status</th><th>Outcome</th><th></th></tr></thead><tbody>${list.map(i=>{const c=customers[i.customer];return `<tr><td><button class="link-btn" onclick="profile(${c.id})">${c.name}</button><small style="display:block;margin-top:5px">${c.code}</small></td><td>${pill(c)}<small style="display:block;margin-top:7px">${reason(c)}</small></td><td>${esc(i.assignee)}</td><td>${short(i.deadline)} ${i.deadline.slice(0,4)}</td><td><span class="badge">${esc(i.status)}</span></td><td>${esc(i.outcome)}</td><td><button onclick="interventionForm(${c.id},${i.id})">Manage ↗</button></td></tr>`}).join('')||'<tr><td colspan="7" class="empty">No matching interventions. Select a customer to create a follow-up.</td></tr>'}</tbody></table></div><div class="footer"><span>${list.length} intervention records</span><span>Changes persist in this browser</span></div></div>`}
function debounceIntervention(input){clearTimeout(window.searchTimer);const pos=input.selectionStart;window.searchTimer=setTimeout(()=>{renderContent();const el=document.querySelector('.filters input');el?.focus();el?.setSelectionRange(pos,pos)},220)}
function cohortRows(){const list=customers.filter(c=>(!cohortChannel||c.channel===cohortChannel)&&(!cohortProduct||c.product===Number(cohortProduct)-1)),groups={};for(const c of list){const first=c.completed[0];if(!first)continue;const key=first.date.slice(0,7);(groups[key]??=[]).push(c)}return Object.entries(groups).sort(([a],[b])=>a.localeCompare(b)).map(([month,cs])=>({month,size:cs.length,values:Array.from({length:7},(_,m)=>{const d=new Date(month+'-01T00:00:00Z'),start=new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth()+m,1)).toISOString().slice(0,10),end=new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth()+m+1,1)).toISOString().slice(0,10);if(end>D.asOf)return null;return cs.filter(c=>c.completed.some(o=>o.date>=start&&o.date<end)).length/cs.length})}))}
function cohort(){const rows=cohortRows();return header('Cohort analysis','See when customers return—and where the lifecycle needs attention.',false)+`<p class="section-intro">Cohorts start in each customer's first completed purchase month. A cell is the share purchasing in that calendar month, not cumulative survival. Immature observation months remain blank.</p><div class="panel table-panel"><div class="panel-head"><div><h2>Monthly purchase retention</h2><p>First completed purchase cohort · 2025–2026</p></div><button onclick="exportReport('cohorts')">⇩ Export CSV</button></div><div class="filters"><select aria-label="Cohort channel" onchange="cohortChannel=this.value;renderContent()"><option value="">All acquisition channels</option>${options(['Organic','Meta Ads','Google Ads','Referral','Influencer'],cohortChannel)}</select><select aria-label="Cohort product" onchange="cohortProduct=this.value;renderContent()"><option value="">All products</option>${D.products.map(p=>`<option value="${p.id+1}" ${cohortProduct===String(p.id+1)?'selected':''}>${p.name}</option>`).join('')}</select></div><div class="table-wrap"><table class="heat"><thead><tr><th>Acquisition month</th><th>Customers</th>${Array.from({length:7},(_,i)=>`<th>Month ${i}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr><td>${date(r.month+'-01').toLocaleDateString('en-IN',{month:'short',year:'numeric',timeZone:'UTC'})}</td><td>${r.size}</td>${r.values.map((v,i)=>v==null?'<td style="background:#fafbf7;color:#c0c7b8" title="Observation month is not complete">—</td>':`<td style="background:rgba(58,120,77,${.07+v*.72});color:${v>.6?'white':'#426145'}" title="${r.month} · Month ${i}: ${pct(v)} of ${r.size} customers">${pct(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="footer"><span>— = not yet fully observed</span><span>Lower retention ░ ▒ ▓ Higher retention</span></div></div><div class="insight">Compare channels and product categories before prioritising a lifecycle stage. Cohort differences are descriptive and may reflect acquisition mix, seasonality, or customer differences.</div>`}
function productRows(){const start=new Date(date(D.asOf)-period*86400000).toISOString().slice(0,10);return D.products.map(p=>{const cs=customers.filter(c=>c.product===p.id&&(!channelFilter||c.channel===channelFilter)&&c.first>=start),m=metrics(cs),second=cs.filter(c=>c.count>1).map(c=>days(c.completed[1].date,c.completed[0].date)),os=cs.flatMap(c=>c.orders);return {...p,customers:cs.length,repeat:m.repeat,retention:m.retention,churn:m.churn,revenue:m.rev,clv:m.clv,second:second.length?second.reduce((s,x)=>s+x,0)/second.length:null,refund:os.filter(o=>o.status==='refunded').length/Math.max(1,os.length)}})}
function productsView(){const rows=productRows();return header('Product performance','Understand replenishment patterns across your haircare portfolio.')+`<div class="notice">Showing customers acquired in the selected period and their observed orders. Each product has its own estimated consumption cycle. Differences are descriptive, not evidence of product-caused retention.</div><div class="two-grid">${panel('Revenue contribution','All observed revenue for customers in acquisition window',barChart(customers.filter(c=>c.first>=new Date(date(D.asOf)-period*86400000).toISOString().slice(0,10)&&(!channelFilter||c.channel===channelFilter)),'revenue'))}${panel('Product replenishment cycles','Expected consumption assumptions used in the demo',D.products.map(p=>`<div class="hbar-row"><span>${p.name}</span><div class="hbar-track"><div style="width:${p.cycle/60*100}%"></div></div><b>${p.cycle}d</b></div>`).join(''))}</div><div class="panel table-panel"><div class="panel-head"><div><h2>Product retention scorecard</h2><p>Historical value, refunds, repeat purchases, and refill status</p></div><button onclick="exportReport('products')">⇩ Export CSV</button></div><div class="filters"><select aria-label="Product acquisition channel" onchange="channelFilter=this.value;renderContent()"><option value="">All acquisition channels</option>${options(['Organic','Meta Ads','Google Ads','Referral','Influencer'],channelFilter)}</select></div><div class="table-wrap"><table><thead><tr><th>Product category</th><th>Customers</th><th>Repeat rate</th><th>2nd order interval</th><th>Retention</th><th>Churn</th><th>Revenue</th><th>Refund rate</th><th>Avg. value</th></tr></thead><tbody>${rows.map(p=>`<tr><td>${p.name}<small style="display:block;margin-top:5px">${p.cycle}-day cycle</small></td><td>${fmt(p.customers)}</td><td>${pct(p.repeat)}</td><td>${p.second==null?'—':Math.round(p.second)+' days'}</td><td>${pct(p.retention)}</td><td>${pct(p.churn)}</td><td>${money(p.revenue)}</td><td>${pct(p.refund)}</td><td>${money(p.clv)}</td></tr>`).join('')}</tbody></table></div></div>`}
function campaignForm(){if(settings.role==='Business Analyst'){toast('Business Analyst is a read-only demo role.');return}openDrawer(`<div class="drawer-head"><h2>Create demo campaign</h2><button onclick="closeDrawer()">✕</button></div><div class="notice">Simulation only. No messages are sent and no CRM is connected.</div><form class="form" onsubmit="createCampaign(event)"><label>Campaign name<input name="name" required maxlength="100" placeholder="November replenishment outreach"></label><label>Strategy<select name="type">${options(['Replenishment reminder','Product education','Feedback request','Support follow-up','Re-engagement'],'')}</select></label><label>Target risk group<select name="risk">${options(['High','Critical','Medium','Low'],'High')}</select></label><button class="primary">Create simulated campaign</button></form>`)}
async function createCampaign(e){e.preventDefault();const v=Object.fromEntries(new FormData(e.target));if(apiMode){try{await api('campaigns','POST',v);await syncOperations();closeDrawer();shell();toast('Campaign saved.')}catch(err){toast(err.message)}return}campaigns.unshift({id:Date.now(),...v,status:'Draft',created:D.asOf});put('campaigns',campaigns);closeDrawer();shell();toast('Demo campaign created. Simulate it to inspect delivery and response outcomes.')}
async function runCampaign(id){if(settings.role==='Business Analyst'){toast('Business Analyst is a read-only demo role.');return}if(apiMode){try{await api('campaigns/'+id+'/simulate','POST');await syncOperations();renderContent();toast('Synthetic campaign simulation saved.')}catch(err){toast(err.message)}return}const camp=campaigns.find(c=>c.id===id);const cs=customers.filter(c=>c.risk===camp.risk);const targeted=cs.length,contacted=cs.filter(c=>c.id%10!==0),delivered=contacted.filter(c=>c.id%13!==0),clicked=delivered.filter(c=>c.id%4===0),converted=clicked.filter(c=>c.id%3===0);Object.assign(camp,{status:'Simulated',targeted,contacted:contacted.length,delivered:delivered.length,clicks:clicked.length,conversions:converted.length,revenue:converted.reduce((s,c)=>s+D.products[c.product].price,0),cost:contacted.length*.75});put('campaigns',campaigns);renderContent();toast('Simulation complete. Results are generated demo outcomes; no customer was contacted.')}
function campaignsView(){return header('Retention campaigns','Compare outreach strategies and keep attribution honest.',false)+`<div class="page-head"><span class="muted" style="font-size:12px">${campaigns.length} campaigns · Browser-local simulation</span><button class="primary" onclick="campaignForm()">＋ Create campaign</button></div><div class="notice">Campaign execution is simulated with deterministic synthetic responses, not an inference of effectiveness. Campaign-associated revenue below is simulated; incremental retention is not measured because no controlled experiment has been run.</div>${campaigns.map(c=>`<div class="panel campaign-card"><div class="panel-head"><div><h2>${esc(c.name)}</h2><p>${esc(c.type)} · ${c.risk} risk customers · ${c.created}</p></div><span class="badge">${c.status}</span></div>${c.status==='Draft'?`<p class="section-intro">Review a synthetic outreach simulation for the selected risk group.</p><button onclick="runCampaign(${c.id})">▷ Run simulation</button>`:`<div class="campaign-stats">${[['Targeted',fmt(c.targeted)],['Contacted',fmt(c.contacted)],['Delivery rate',pct(c.delivered/Math.max(1,c.contacted))],['Click-through',pct(c.clicks/Math.max(1,c.delivered))],['Reorder conversion',pct(c.conversions/Math.max(1,c.delivered))],['Simulated revenue',money(c.revenue)],['Cost / reorder',money(c.cost/Math.max(1,c.conversions))],['Incremental retention','Not measured']].map(([n,v])=>`<div><small>${n}</small><strong>${v}</strong></div>`).join('')}</div><p class="forecast-note">${fmt(c.clicks)} clicks · ${fmt(c.conversions)} simulated reorders · revenue associated with campaign responses, without a causal attribution claim.</p>`}</div>`).join('')||'<div class="panel empty">Create a campaign to explore an outreach strategy.</div>'}`}
function reports(){return header('Reports & analytics','Take a consistent view of customer health into your next review.')+`<div class="notice">Exports contain synthetic data only. Customer exports respect the customer explorer filters; summary and monthly revenue use the selected reporting period. Cohort exports retain the cohort module filters.</div><div class="report-grid">${[['summary','Executive retention summary','Current customer health, exposure, and period revenue'],['customers','Customer intelligence export','Customer signals, risks, values, and recommendations'],['products','Product performance','Acquisition-window product scorecard'],['cohorts','Cohort retention matrix','Monthly purchasing, with immature cells blank'],['interventions','Intervention outcomes','Assignments, responses, and observational results'],['monthly','Monthly churn & revenue','Monthly refill status, retention, and revenue']].map(([k,n,s])=>`<div class="panel report-card"><div class="report-icon">▧</div><div><h2>${n}</h2><p>${s}</p></div><button onclick="exportReport('${k}')">CSV ⇩</button></div>`).join('')}</div><div class="insight"><b>Report definitions</b><br>Active = within expected product refill cycle + grace. Observed churn = outside that window. Customer value = historical completed-order revenue. Revenue at risk = high/critical historical value weighted by probability; this is an exposure proxy. Repeat-order revenue must not be described as revenue saved by interventions.</div>`}
function download(name,rows){if(!rows.length){toast('No matching records to export.');return}const cols=Object.keys(rows[0]),quote=v=>'"'+String(v??'').replace(/^[=+@\-\t\r]/,"'$&").replace(/"/g,'""')+'"',csv='\uFEFF'+[cols,...rows.map(r=>cols.map(k=>r[k]))].map(row=>row.map(quote).join(',')).join('\r\n'),url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=name+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Synthetic data report downloaded.')}
function exportReport(kind){let rows=[];if(kind==='customers')rows=filtered().map(c=>({synthetic:true,id:c.code,name:c.name,age:c.age,product:D.products[c.product].name,channel:c.channel,stage:c.stage,registered:c.registered,first:c.first,last:c.last,orders:c.count,revenue:c.revenue,aov:c.revenue/Math.max(1,c.count),frequency_days:c.freq,cycle_days:c.cycle,engagement_30d:c.engagement,probability:c.probability,risk:c.risk,reason:reason(c),recommendation:recommendation(c)}));if(kind==='summary'){const m=metrics(scoped());rows=Object.entries(m).map(([metric,value])=>({synthetic:true,as_of:D.asOf,reporting_days:period,metric,value}))}if(kind==='products')rows=productRows().map(p=>({synthetic:true,...p}));if(kind==='cohorts')rows=cohortRows().map(r=>({synthetic:true,month:r.month,customers:r.size,...Object.fromEntries(r.values.map((v,i)=>['month_'+i,v==null?'':v]))}));if(kind==='interventions')rows=interventions.map(i=>({synthetic:true,...i,customer:customers[i.customer].code,history:JSON.stringify(i.history)}));if(kind==='monthly')rows=series(scoped()).map(r=>({synthetic:true,...r}));download('retention-radar-'+kind+'-'+D.asOf,rows)}
function settingsView(){return header('Workspace settings','Configure operational definitions and explore demo roles.',false)+`<div class="notice">Hosted demo role selection illustrates permissions; it is not secure authentication. The downloadable FastAPI backend enforces signed login tokens and server-side roles. Hosted changes persist only in this browser.</div><div class="panel settings-list"><h2>Business configuration</h2><form onsubmit="saveSettings(event)" class="form"><div class="setting-row"><div><h3>Operational replenishment grace</h3><p>Extra days after each product's consumption cycle. Updates active / dormant definitions; fixed model predictions remain unchanged.</p></div><input name="grace" type="number" min="0" max="90" required value="${settings.grace}" aria-label="Grace period days"></div><div class="setting-row"><div><h3>Risk thresholds</h3><p>Probability cutoffs for medium, high, and critical risk. Keep them strictly increasing.</p></div><div style="display:flex;flex-direction:column;gap:8px">${['medium','high','critical'].map(k=>`<label>${k} <input name="${k}" type="number" step=".01" min=".01" max=".99" required value="${settings[k]}" aria-label="${k} risk threshold"></label>`).join('')}</div></div><div class="setting-row"><div><h3>Demo user role</h3><p>Managers and customer success executives manage follow-ups. Analysts explore data and export reports.</p></div><select name="role" aria-label="Demo role" ${apiMode?'disabled':''}>${options(['Retention Manager','Business Analyst','Customer Success Executive'],settings.role)}</select></div><div class="setting-row"><div><h3>Prediction horizon</h3><p>The published model uses 30 days. Alternative 60/90-day experiments require Python retraining and new mature labels; they are not simulated by scaling scores.</p></div><span class="badge">30 days · fixed model</span></div><button class="primary" type="submit" style="align-self:flex-start">Save configuration</button></form><div class="setting-row"><div><h3>Connected services</h3><p>CRM, messaging, and external customer data are not connected. Campaigns run as clearly labelled simulations.</p></div><span class="badge">Demo mode</span></div></div>`}
function saveSettings(e){e.preventDefault();const v=Object.fromEntries(new FormData(e.target));if(!(Number(v.medium)<Number(v.high)&&Number(v.high)<Number(v.critical))){toast('Thresholds must increase: medium < high < critical.');return}if(apiMode)v.role=settings.role;settings={...settings,...v,grace:Number(v.grace),medium:Number(v.medium),high:Number(v.high),critical:Number(v.critical)};put('settings',settings);refresh();shell();toast('Workspace configuration saved.')}
function renderContent(){const renderers={'Churn Intelligence':churnIntelligence,'Overview':overviewV2,'Customer Intelligence':workspaceV2,'Model Intelligence':modelV2,'Customer Segments':segmentation,'Campaign Intelligence':campaignsView,'Cohort Analysis':cohort,'Product Analytics':productsView,'Retention Actions':actionsV2,'Reports':reports,'Settings':settingsView};document.getElementById('content').innerHTML=renderers[view]().replaceAll('Browser-local demonstration records',apiMode?'PostgreSQL demonstration records':'Browser-local demonstration records').replaceAll('Browser-local simulation',apiMode?'Database-backed simulation':'Browser-local simulation').replaceAll('Stored in this browser in the hosted demo.',apiMode?'Stored in the authenticated database.':'Stored in this browser in the hosted demo.').replaceAll('Changes persist in this browser',apiMode?'Changes persist in PostgreSQL':'Changes persist in this browser').replaceAll('Interventions and outcomes in this hosted demo are stored in your browser.',apiMode?'Interventions and outcomes are stored in PostgreSQL.':'Interventions and outcomes in this hosted demo are stored in your browser.')+`<div class="page-foot"><span>RETENTION RADAR &nbsp; / &nbsp; MAN MATTERS DEMO</span><span>Detect → Understand → Prioritise → Intervene → Measure → Learn</span></div>`}
async function init(){try{if(apiMode){if(!authToken){backendLogin();return}try{const me=await api('me');settings.role=me.role;D=await api('workspace');await syncOperations()}catch(err){authToken=null;sessionStorage.removeItem('rr-token');backendLogin();document.getElementById('login-error').textContent=err.message;return}}else{const response=await fetch('data.json');if(!response.ok)throw Error('Dataset could not be loaded');D=await response.json();}orderMap={};ticketMap={};eventMap={};for(const o of D.orders)(orderMap[o.customer]??=[]).push(o);for(const t of D.tickets)(ticketMap[t.customer]??=[]).push(t);for(const e of D.engagements)(eventMap[e.customer]??=[]).push(e);refresh();if(!apiMode&&!getStore('seeded',false)){const top=[...customers].filter(c=>['Critical','High'].includes(c.risk)).sort((a,b)=>b.probability-a.probability).slice(0,14);interventions=top.map((c,i)=>({id:100+i,customer:c.id,assignee:['Priya Nair','Rohit Mehta','Neha Singh'][i%3],deadline:'2026-11-0'+(2+i%6),status:['Pending','Assigned','In Progress','Contacted','Resolved','Unsuccessful'][i%6],outcome:i%6===5?'Churned':'Not observed',notes:'Seeded synthetic follow-up example.',action:recommendation(c),created:'2026-10-28',history:[{at:'2026-10-28',status:'Pending',assignee:'Unassigned',notes:'Synthetic demonstration case created.'}]}));campaigns=[{id:1,name:'A timely reminder, a healthier routine',type:'Replenishment reminder',risk:'High',status:'Draft',created:'2026-11-01'},{id:2,name:'Let’s understand your experience',type:'Support follow-up',risk:'Critical',status:'Draft',created:'2026-11-01'}];put('interventions',interventions);put('campaigns',campaigns);put('seeded',true)}const hash=decodeURIComponent(location.hash.slice(1));if(navs.includes(hash))view=hash;shell()}catch(e){document.getElementById('app').innerHTML=`<div class="loading"><h2>Workspace could not load</h2><p>${esc(e.message)}</p><button onclick="location.reload()">Try again</button></div>`}}

